/**
 * Authenticated shell: resolves the session and redirects to /login when absent.
 *
 * Owner D. This is the only place the signed-in/signed-out decision is made for
 * the whole dashboard tree. `src/proxy.ts` also looks at the session cookie, but
 * only to short-circuit obvious cases — the cookie being present is not proof
 * the session is live, so the real check happens here.
 *
 * Must call (do not reimplement): getSessionPrincipal
 */

import { redirect } from "next/navigation";
import type { ReactNode } from "react";
import { getSessionPrincipal } from "@/lib/session";

type LayoutParams = Record<string, never>;

export const dynamic = "force-dynamic";

export default async function Layout(props: {
  children: ReactNode;
  params: Promise<LayoutParams>;
}) {
  // Next.js 16: params is a Promise and MUST be awaited.
  await props.params;

  const principal = await getSessionPrincipal();
  if (principal === null) {
    redirect("/login");
  }

  return <div className="min-h-screen bg-slate-50">{props.children}</div>;
}
/**
 * Org chooser: lists the organizations the signed-in user belongs to and
 * redirects when there is exactly one.
 *
 * Owner D. This is the only route in the dashboard tree without an `[orgSlug]`,
 * so it is also the only one that works with a `SessionPrincipal` instead of an
 * `Actor` — there is no tenant to scope to until the choice is made.
 */

import Link from "next/link";
import { redirect } from "next/navigation";
import type { Metadata } from "next";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { getSessionPrincipal } from "@/lib/session";
import { listOrganizationsForUser } from "@/server/services/organization-service";

type PageParams = Record<string, never>;

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Choose an organization",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  await props.params;
  await props.searchParams;

  const principal = await getSessionPrincipal();
  if (principal === null) {
    throw new UnauthorizedActionError();
  }

  const organizations = await listOrganizationsForUser(principal.userId);

  // One organization is the overwhelmingly common case; do not make people
  // click through a list of one.
  if (organizations.length === 1) {
    redirect(`/${organizations[0].slug}`);
  }

  return (
    <main className="mx-auto max-w-lg px-6 py-20">
      <h1 className="text-xl font-semibold">Choose an organization</h1>
      <p className="mt-2 text-sm text-slate-600">
        Signed in as {principal.email}.
      </p>

      {organizations.length === 0 ? (
        <p className="mt-8 rounded-md border border-dashed border-slate-300 p-6 text-sm text-slate-600">
          You are not a member of any organization yet. Ask a colleague to invite
          you, or create one of your own.
        </p>
      ) : (
        <ul className="mt-8 space-y-2">
          {organizations.map((org) => (
            <li key={org.id}>
              <Link
                href={`/${org.slug}`}
                className="flex items-center justify-between rounded-md border border-slate-200 bg-white px-4 py-3 text-sm"
              >
                <span className="font-medium">{org.name}</span>
                <span className="text-xs uppercase tracking-wide text-slate-400">
                  {org.plan}
                </span>
              </Link>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}
/**
 * Returns the current `SessionPrincipal`, or 401.
 *
 * Owner D. Used by the client to re-check the session after a tab has been
 * asleep. It returns the principal, never the token — the cookie is httpOnly
 * and stays that way.
 *
 * Must call (do not reimplement): getSessionPrincipal
 */

import { getSessionPrincipal } from "@/lib/session";
import { errorResponse, failure } from "@/app/api/_lib/responses";

export const dynamic = "force-dynamic";

export async function GET(request: Request): Promise<Response> {
  void request;

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      return failure("unauthorized", "No active session.");
    }

    return Response.json({
      userId: principal.userId,
      email: principal.email,
      activeOrgId: principal.activeOrgId,
      expiresAt: principal.expiresAt,
    });
  } catch (error) {
    return errorResponse(error);
  }
}
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { SESSION_COOKIE_NAME } from "@/schemas/session";

/**
 * Next.js 16 renamed `middleware.ts` to `proxy.ts` and the exported function
 * from `middleware` to `proxy`. Do not reintroduce the old names — Next 16
 * ignores them silently and every route becomes public.
 *
 * This proxy only decides "is there a session cookie at all". Real
 * authorization happens in the layouts and Server Actions via `can()`; a proxy
 * cannot reach the database.
 */

const PUBLIC_PREFIXES = [
  "/",
  "/pricing",
  "/changelog",
  "/about",
  "/login",
  "/register",
  "/reset-password",
  "/invite",
  "/api/health",
  "/api/webhooks",
];

function isPublicPath(pathname: string): boolean {
  return PUBLIC_PREFIXES.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );
}

export function proxy(request: NextRequest): NextResponse {
  const { pathname, search } = request.nextUrl;

  if (isPublicPath(pathname)) {
    return NextResponse.next();
  }

  const session = request.cookies.get(SESSION_COOKIE_NAME);
  if (!session?.value) {
    const loginUrl = new URL("/login", request.url);
    loginUrl.searchParams.set("next", `${pathname}${search}`);
    return NextResponse.redirect(loginUrl);
  }

  const response = NextResponse.next();
  response.headers.set("x-taskflow-authenticated", "1");
  return response;
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico).*)"],
};
"use server";

/**
 * Signs a user in and sets the session cookie.
 *
 * Owner D. Runs before any tenant is known, so it cannot go through
 * `withAction()` — there is no `Actor` to resolve yet. The rate limit is
 * charged against the anonymous bucket to blunt credential stuffing.
 *
 * Must call (do not reimplement): loginSchema, setSessionCookie,
 * consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { RateLimitedError } from "@/actions/_lib/action-errors";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import { setSessionCookie } from "@/lib/session";
import { loginSchema } from "@/schemas/auth";
import { login } from "@/server/services/auth-service";
import { resolveSession } from "@/server/services/session-service";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

const LOGIN_BUCKET = "auth:login";

export async function loginAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = loginSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, LOGIN_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(LOGIN_BUCKET, verdict.resetAt);
    }

    const { token } = await login(parsed.data);
    const principal = await resolveSession(token);
    if (principal === null) {
      throw new UnauthorizedActionError("That sign-in could not be completed.");
    }

    await setSessionCookie(token, principal.expiresAt);
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

