/**
 * Pending invitations, keyed by token hash for the unauthenticated accept flow.
 */
import { and, count, desc, eq, gt, inArray, isNull, ne, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invitations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvitation } from "./_mappers";
import type { CreateInvitationInput } from "@/schemas/invitation";
import type { InvitationId, IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Invitation } from "@/types/member";

/** Unit behind `expiresInDays`: one calendar day. */
const EXPIRY_UNIT_MS = 24 * 60 * 60 * 1000;

/**
 * An invitation is pending while it has not been accepted, revoked or
 * expired. Only pending rows hold a seat or block a second invite to the same
 * address, so every "pending" read goes through this one predicate.
 */
function pendingPredicate(now: IsoTimestamp = toIsoTimestamp(new Date())) {
  return and(
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
    gt(invitations.expiresAt, now),
  );
}

export async function insertInvitation(
  orgId: OrgId,
  input: CreateInvitationInput,
  invitedBy: UserId,
  tokenHash: string,
): Promise<Invitation> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(
    new Date(Date.now() + input.expiresInDays * EXPIRY_UNIT_MS),
  );

  const row = getDb()
    .insert(invitations)
    .values({
      id: newId(),
      orgId,
      email: input.email,
      role: input.role,
      invitedBy,
      tokenHash,
      expiresAt,
      acceptedAt: null,
      revokedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvitation(row);
}

/**
 * The accept flow runs before a session exists, so this is the one read in the
 * repository layer that is not scoped by `orgId` — the token hash is the
 * credential and carries the tenant with it.
 */
export async function findInvitationByTokenHash(
  tokenHash: string,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
  return row ? toInvitation(row) : null;
}

/** Any invitation of the org, whatever its state. */
export async function findInvitationById(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
    .where(and(orgPredicate(invitations.orgId, orgId), pendingPredicate()))
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

/**
 * The subset of `emails` (lower-cased) that already have a pending invitation
 * in the org. Addresses are compared without regard to letter case.
 * `excludeId` leaves one invitation out — the one a re-send is replacing.
 */
export async function findPendingInvitationEmails(
  orgId: OrgId,
  emails: readonly string[],
  excludeId?: InvitationId,
): Promise<readonly string[]> {
  if (emails.length === 0) return [];

  const lowered = sql<string>`lower(${invitations.email})`;
  const rows = getDb()
    .selectDistinct({ email: lowered })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        pendingPredicate(),
        inArray(lowered, emails.map((email) => email.toLowerCase())),
        excludeId === undefined ? undefined : ne(invitations.id, excludeId),
      ),
    )
    .all();

  return rows.map((row) => row.email);
}

/**
 * Consumes the invitation. The update only matches a row that is still
 * pending, so an invitation can be used once and a revoked or expired one
 * never flips to accepted.
 */
export async function markInvitationAccepted(
  orgId: OrgId,
  invitationId: InvitationId,
  at: IsoTimestamp,
): Promise<Invitation> {
  const row = getDb()
    .update(invitations)
