        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

